 if not r['expost_cap_removed'] and r['strategy'] in names and r['cohort']!='2025回放':text.append(f"|{r['cohort']}|{names[r['strategy']]}|{r['n']}|{r['positive']}|{r['zero']}|{r['negative']}|{r['hit_rate']:.2%}|")
